-- GENERATED by scripts/generate-seed.ts from data/*.json. Do not edit by hand:
-- change the data files and run `npm run seed:generate`.
-- Safe to run more than once.

-- Reward ids are md5 of a stable name, so re-running updates instead of duplicating.

-- The welcome gift is the butter-croissant reward (data/rewards.json welcome_reward):
-- config.welcome.rewardId. Re-running sets it again and keeps every other setting.
values ('overoll', 'Overoll Croissanterie', 'el', 'Europe/Athens', jsonb_build_object('welcome', jsonb_build_object('rewardId', md5('overoll:reward:butter-croissant')::uuid::text)))
on conflict (slug) do update set
  name = excluded.name,
  config = public.brands.config || jsonb_build_object(
    'welcome', coalesce(public.brands.config -> 'welcome', '{}'::jsonb) || jsonb_build_object('rewardId', md5('overoll:reward:butter-croissant')::uuid::text));

on conflict (brand_id, code) do update set
  name = excluded.name, address = excluded.address, city = excluded.city, country = excluded.country,
  latitude = excluded.latitude, longitude = excluded.longitude, phone = excluded.phone,
  opening_hours = excluded.opening_hours;

on conflict (id) do update set
  name_el = excluded.name_el, name_en = excluded.name_en,
  description_el = excluded.description_el, description_en = excluded.description_en,
  category = excluded.category, shelf_price_cents = excluded.shelf_price_cents,
  base_cost = excluded.base_cost, min_tier = excluded.min_tier, sort_order = excluded.sort_order;
